-- Additive operations schema. No existing account or business row is changed.
CREATE TABLE ops_permissions(user_id TEXT PRIMARY KEY REFERENCES users(id),production_review INTEGER NOT NULL DEFAULT 0 CHECK(production_review IN(0,1)),materials INTEGER NOT NULL DEFAULT 0 CHECK(materials IN(0,1)),quality INTEGER NOT NULL DEFAULT 0 CHECK(quality IN(0,1)),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE ops_items(id TEXT PRIMARY KEY,drawing TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,model TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('part','assembly')),unit TEXT NOT NULL,supplier TEXT NOT NULL,source TEXT NOT NULL,criteria TEXT NOT NULL,warnings TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE ops_runs(production_id TEXT PRIMARY KEY REFERENCES production(id),item_id TEXT NOT NULL REFERENCES ops_items(id),lot_code TEXT NOT NULL,process TEXT NOT NULL,note TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','approved','rejected')),reviewer_id TEXT REFERENCES users(id),reviewed_at TEXT,review_reason TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE ops_lots(id TEXT PRIMARY KEY,item_id TEXT NOT NULL REFERENCES ops_items(id),code TEXT NOT NULL,supplier TEXT NOT NULL,origin TEXT NOT NULL CHECK(origin IN('receipt','production')),production_id TEXT UNIQUE REFERENCES ops_runs(production_id),received INTEGER NOT NULL CHECK(received BETWEEN 1 AND 999999),balance INTEGER NOT NULL CHECK(balance BETWEEN 0 AND 999999),status TEXT NOT NULL CHECK(status IN('pending','released','held')),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(item_id,code));
CREATE TABLE ops_movements(id TEXT PRIMARY KEY,lot_id TEXT NOT NULL REFERENCES ops_lots(id),kind TEXT NOT NULL CHECK(kind IN('receipt','production','issue','adjust','dispose')),quantity INTEGER NOT NULL CHECK(quantity!=0),reason TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE ops_inspections(id TEXT PRIMARY KEY,lot_id TEXT NOT NULL REFERENCES ops_lots(id),stage TEXT NOT NULL CHECK(stage IN('incoming','process','shipping')),sample INTEGER NOT NULL CHECK(sample>0),failed INTEGER NOT NULL CHECK(failed>=0 AND failed<=sample),decision TEXT NOT NULL CHECK(decision IN('pass','fail')),criteria TEXT NOT NULL,measurements TEXT NOT NULL,reason TEXT NOT NULL,item_snapshot TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,CHECK(decision!='pass' OR failed=0));
CREATE TABLE ops_requests(user_id TEXT NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,payload TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(user_id,request_key));
CREATE INDEX ops_lots_status ON ops_lots(status,created_at,id);
CREATE INDEX ops_runs_status ON ops_runs(status,production_id);
CREATE INDEX ops_inspections_lot ON ops_inspections(lot_id,created_at,id);
CREATE INDEX ops_movements_lot ON ops_movements(lot_id,created_at,id);
CREATE TRIGGER ops_production_lock BEFORE UPDATE ON production WHEN EXISTS(SELECT 1 FROM ops_runs WHERE production_id=OLD.id AND status='approved') BEGIN SELECT RAISE(ABORT,'approved production is locked'); END;
CREATE TRIGGER ops_production_delete BEFORE DELETE ON production WHEN EXISTS(SELECT 1 FROM ops_runs WHERE production_id=OLD.id) BEGIN SELECT RAISE(ABORT,'operations production must be retained'); END;
CREATE TRIGGER ops_movements_no_update BEFORE UPDATE ON ops_movements BEGIN SELECT RAISE(ABORT,'operations history is immutable'); END;
CREATE TRIGGER ops_movements_no_delete BEFORE DELETE ON ops_movements BEGIN SELECT RAISE(ABORT,'operations history is immutable'); END;
CREATE TRIGGER ops_inspections_no_update BEFORE UPDATE ON ops_inspections BEGIN SELECT RAISE(ABORT,'operations history is immutable'); END;
CREATE TRIGGER ops_inspections_no_delete BEFORE DELETE ON ops_inspections BEGIN SELECT RAISE(ABORT,'operations history is immutable'); END;
CREATE TRIGGER ops_requests_no_update BEFORE UPDATE ON ops_requests BEGIN SELECT RAISE(ABORT,'operations history is immutable'); END;
CREATE TRIGGER ops_requests_no_delete BEFORE DELETE ON ops_requests BEGIN SELECT RAISE(ABORT,'operations history is immutable'); END;
-- worker_revision exists only on D1.
CREATE TRIGGER revision_ops_permissions_insert AFTER INSERT ON ops_permissions BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_permissions_update AFTER UPDATE ON ops_permissions BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_permissions_delete AFTER DELETE ON ops_permissions BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_items_insert AFTER INSERT ON ops_items BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_items_update AFTER UPDATE ON ops_items BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_items_delete AFTER DELETE ON ops_items BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_runs_insert AFTER INSERT ON ops_runs BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_runs_update AFTER UPDATE ON ops_runs BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_runs_delete AFTER DELETE ON ops_runs BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_lots_insert AFTER INSERT ON ops_lots BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_lots_update AFTER UPDATE ON ops_lots BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_lots_delete AFTER DELETE ON ops_lots BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_movements_insert AFTER INSERT ON ops_movements BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_movements_update AFTER UPDATE ON ops_movements BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_movements_delete AFTER DELETE ON ops_movements BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_inspections_insert AFTER INSERT ON ops_inspections BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_inspections_update AFTER UPDATE ON ops_inspections BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_inspections_delete AFTER DELETE ON ops_inspections BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_requests_insert AFTER INSERT ON ops_requests BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_requests_update AFTER UPDATE ON ops_requests BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER revision_ops_requests_delete AFTER DELETE ON ops_requests BEGIN UPDATE worker_revision SET revision=revision+1 WHERE id=1; END;
